def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_n(n, sequence_length=38):
    for i in range(sequence_length):
        k = n + i
        s_k = sum_digits(k)
        if s_k % 11 == 0:
            return False, k, s_k
    return True, None, None

